Az alábbi egyfájlos verzió a vLLM által dokumentált `--trust-remote-code` és `trust_remote_code` beállítást következetesen átadja, miközben a Tensormesh dokumentációja szerint a deployment konfiguráció részeként kezeli a vLLM-paramétereket. A hálózati hívások időkorlátot kapnak, ami a `fetch` megszakításának támogatott mintája `AbortSignal.timeout()` használatával.[1][2][3]

```javascript
"use strict";

const fs = require("fs");

const CONTROL_PLANE_BASE = (process.env.TENSORMESH_CONTROL_PLANE_BASE || "").replace(/\/+$/, "");
const HF_MODEL_ID = process.env.HF_MODEL_ID || "fno2010/MiniMax-M2.7-TQ3";
const ACTIVE_MODEL_ID = process.env.ACTIVE_MODEL_ID || "7ff03808-a399-475d-ae33-c18356d74350";
const TOKEN_FILE = process.env.TENSORMESH_TOKEN_FILE || "/tmp/tm_token.txt";
const REQUEST_TIMEOUT_MS = toPositiveInt(process.env.REQUEST_TIMEOUT_MS, 30000);
const POLL_INTERVAL_MS = toPositiveInt(process.env.POLL_INTERVAL_MS, 10000);
const MAX_POLLS = toPositiveInt(process.env.MAX_POLLS, 120);
const GPU_COUNT = toPositiveInt(process.env.GPU_COUNT, 2);
const GPU_TYPE = process.env.GPU_TYPE || "GPU_TYPE_H200";
const MAX_MODEL_LEN = toPositiveInt(process.env.MAX_MODEL_LEN, 196608);
const TENSOR_PARALLEL_SIZE = toPositiveInt(process.env.TENSOR_PARALLEL_SIZE, GPU_COUNT);
const MAX_NUM_SEQS = toPositiveInt(process.env.MAX_NUM_SEQS, 256);
const MIN_REPLICAS = toNonNegativeInt(process.env.MIN_REPLICAS, 0);
const MAX_REPLICAS = toPositiveInt(process.env.MAX_REPLICAS, 4);
const SCALE_TO_ZERO_DELAY_SECONDS = toNonNegativeInt(process.env.SCALE_TO_ZERO_DELAY_SECONDS, 300);
const SCALE_DOWN_STABILIZATION_WINDOW_SECONDS = toNonNegativeInt(process.env.SCALE_DOWN_STABILIZATION_WINDOW_SECONDS, 60);
const SCALE_UP_STABILIZATION_WINDOW_SECONDS = toNonNegativeInt(process.env.SCALE_UP_STABILIZATION_WINDOW_SECONDS, 30);
const CLOUD_PROVIDER = process.env.CLOUD_PROVIDER || "CLOUD_PROVIDER_NEBIUS";
const NEBIUS_REGION = process.env.NEBIUS_REGION || "NEBIUS_REGION_EU_NORTH_1";

const RUNNING_STATUSES = new Set(["MODEL_STATUS_RUNNING", "RUNNING", "READY"]);
const FAILED_STATUSES = new Set(["MODEL_STATUS_FAILED", "MODEL_STATUS_ERROR", "FAILED", "ERROR"]);

function toPositiveInt(value, fallback) {
  const n = Number.parseInt(String(value ?? ""), 10);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}

function toNonNegativeInt(value, fallback) {
  const n = Number.parseInt(String(value ?? ""), 10);
  return Number.isFinite(n) && n >= 0 ? n : fallback;
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function safeTrim(value) {
  return typeof value === "string" ? value.trim() : "";
}

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function deepMerge(target, source) {
  if (!isPlainObject(target) || !isPlainObject(source)) {
    return source;
  }
  const out = { ...target };
  for (const [key, value] of Object.entries(source)) {
    if (isPlainObject(value) && isPlainObject(out[key])) {
      out[key] = deepMerge(out[key], value);
    } else {
      out[key] = value;
    }
  }
  return out;
}

function parseJsonEnv(name) {
  const raw = process.env[name];
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch (err) {
    throw new Error(`Invalid JSON in ${name}: ${err.message}`);
  }
}

function uniqueStrings(values) {
  return [...new Set(values.filter((v) => typeof v === "string" && v.trim() !== "").map((v) => v.trim()))];
}

function getToken() {
  const envToken =
    safeTrim(process.env.TENSORMESH_CONTROL_PLANE_TOKEN) ||
    safeTrim(process.env.TENSORMESH_API_KEY) ||
    safeTrim(process.env.CONTROL_PLANE_TOKEN);
  if (envToken) return envToken;
  try {
    const fromFile = safeTrim(fs.readFileSync(TOKEN_FILE, "utf8"));
    if (fromFile) return fromFile;
  } catch (_) {}
  return null;
}

function buildHeaders(token) {
  const result = {
    Accept: "application/json",
    "Content-Type": "application/json",
  };
  if (token) result.Authorization = `Bearer ${token}`;
  return result;
}

function safeJsonParse(text) {
  try {
    return JSON.parse(text);
  } catch (_) {
    return { raw: text };
  }
}

function formatPayload(data) {
  if (typeof data === "string") return data;
  try {
    return JSON.stringify(data, null, 2);
  } catch (_) {
    return String(data);
  }
}

function normalizeModel(data) {
  if (isPlainObject(data?.model)) return data.model;
  if (isPlainObject(data)) return data;
  return {};
}

function normalizeEvents(model) {
  return Array.isArray(model?.events) ? model.events : [];
}

function normalizeStatus(status) {
  return String(status || "unknown").trim();
}

function createTimeoutSignal(timeoutMs) {
  if (typeof AbortSignal !== "undefined" && typeof AbortSignal.timeout === "function") {
    return { signal: AbortSignal.timeout(timeoutMs), dispose() {} };
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(new Error(`Timed out after ${timeoutMs}ms`)), timeoutMs);
  return {
    signal: controller.signal,
    dispose() {
      clearTimeout(timer);
    },
  };
}

async function requestJson(url, { method = "GET", token, body, timeoutMs = REQUEST_TIMEOUT_MS } = {}) {
  const timeout = createTimeoutSignal(timeoutMs);
  try {
    const response = await fetch(url, {
      method,
      headers: buildHeaders(token),
      body: body === undefined ? undefined : JSON.stringify(body),
      signal: timeout.signal,
    });
    const text = await response.text();
    const data = safeJsonParse(text);
    return {
      ok: response.ok,
      status: response.status,
      data,
      text,
    };
  } catch (err) {
    const message = err && typeof err.message === "string" ? err.message : String(err);
    if (err?.name === "AbortError" || err?.name === "TimeoutError") {
      throw new Error(`Request timeout for ${method} ${url}: ${message}`);
    }
    throw new Error(`Request failed for ${method} ${url}: ${message}`);
  } finally {
    timeout.dispose();
  }
}

function printEvents(model) {
  for (const event of normalizeEvents(model)) {
    const createdAt = event?.createdAt || "-";
    const eventType = event?.eventType || "EVENT";
    const log = event?.log || "";
    console.error(`  [${createdAt}] ${eventType}: ${log}`);
  }
}

function buildModelName() {
  const explicit = safeTrim(process.env.MODEL_NAME || process.env.SERVED_MODEL_NAME);
  if (explicit) return explicit;
  const suffix = Date.now();
  return `minimax-m27-tq3-${suffix}`;
}

function buildDeployBody() {
  const modelName = buildModelName();
  const extraArgs = uniqueStrings(
    ["--trust-remote-code"].concat(
      safeTrim(process.env.EXTRA_VLLM_ARGS)
        .split(",")
        .map((v) => v.trim())
        .filter(Boolean)
    )
  );

  let body = {
    model_name: modelName,
    model_path: HF_MODEL_ID,
    gpu_count: GPU_COUNT,
    gpu_type: GPU_TYPE,
    trust_remote_code: true,
    args: extraArgs,
    env: {
      HF_TRUST_REMOTE_CODE: "1",
      VLLM_TRUST_REMOTE_CODE: "1",
      TRUST_REMOTE_CODE: "true",
    },
    engine_args: {
      trust_remote_code: true,
      max_model_len: MAX_MODEL_LEN,
      tensor_parallel_size: TENSOR_PARALLEL_SIZE,
      enable_prefix_caching: true,
      enable_chunked_prefill: true,
      max_num_seqs: MAX_NUM_SEQS,
      served_model_name: [modelName],
    },
    vllm_config: {
      trust_remote_code: true,
      max_model_len: MAX_MODEL_LEN,
      tensor_parallel_size: TENSOR_PARALLEL_SIZE,
      enable_prefix_caching: true,
      enable_chunked_prefill: true,
      max_num_seqs: MAX_NUM_SEQS,
      extra_args: extraArgs,
    },
    vllmConfig: {
      trustRemoteCode: true,
      maxModelLen: MAX_MODEL_LEN,
      tensorParallelSize: TENSOR_PARALLEL_SIZE,
      enablePrefixCaching: true,
      enableChunkedPrefill: true,
      maxNumSeqs: MAX_NUM_SEQS,
      extraArgs: extraArgs,
    },
    infra: {
      cloud_provider: CLOUD_PROVIDER,
      nebius_region: NEBIUS_REGION,
    },
    autoscaling_config: {
      enabled: true,
      min_replicas: MIN_REPLICAS,
      max_replicas: MAX_REPLICAS,
      scale_down_policy: {
        scale_to_zero_delay_seconds: SCALE_TO_ZERO_DELAY_SECONDS,
        stabilization_window_seconds: SCALE_DOWN_STABILIZATION_WINDOW_SECONDS,
      },
      scale_up_policy: {
        stabilization_window_seconds: SCALE_UP_STABILIZATION_WINDOW_SECONDS,
      },
    },
  };

  const envPatch = parseJsonEnv("TENSORMESH_DEPLOY_PATCH");
  if (envPatch) {
    body = deepMerge(body, envPatch);
  }

  return body;
}

function printRunningSummary(modelId, model) {
  const gpuType = model?.gpuType || model?.gpu_type || "-";
  const gpuCount = model?.gpuCount ?? model?.gpu_count ?? "-";
  console.log("");
  console.log("[READY] Model is live");
  console.log(`Model ID: ${modelId}`);
  if (model?.modelName) console.log(`Model name: ${model.modelName}`);
  if (model?.model_name) console.log(`Model name: ${model.model_name}`);
  if (model?.modelPath) console.log(`HF path: ${model.modelPath}`);
  if (model?.model_path) console.log(`HF path: ${model.model_path}`);
  if (model?.endpoint) console.log(`Endpoint: ${model.endpoint}`);
  console.log(`GPU: ${gpuCount}x ${gpuType}`);
  if (model?.infra) console.log(`Infra: ${formatPayload(model.infra)}`);
}

async function pollStatus(modelId, token) {
  const modelUrl = `${CONTROL_PLANE_BASE}/v1/models/${encodeURIComponent(modelId)}`;
  for (let i = 0; i < MAX_POLLS; i++) {
    if (i > 0) {
      await sleep(POLL_INTERVAL_MS);
    }

    const response = await requestJson(modelUrl, { token });
    const model = normalizeModel(response.data);

    if (!response.ok) {
      const transient = response.status === 429 || response.status >= 500;
      if (transient) {
        console.error(`[WARN] Status poll failed temporarily - HTTP ${response.status}`);
        console.error(formatPayload(response.data));
        continue;
      }
      throw new Error(`Status poll failed - HTTP ${response.status}\n${formatPayload(response.data)}`);
    }

    const status = normalizeStatus(model.status);
    const gpuType = model?.gpuType || model?.gpu_type || "-";
    const gpuCount = model?.gpuCount ?? model?.gpu_count ?? "-";
    const elapsedSeconds = Math.floor((i * POLL_INTERVAL_MS) / 1000);
    const events = normalizeEvents(model);
    const lastEvent = events.length > 0 ? events[events.length - 1] : null;

    console.log(`[POLL ${i + 1}] status=${status} gpu=${gpuCount}x${gpuType} elapsed=${elapsedSeconds}s`);
    if (lastEvent?.log) {
      console.log(`Last event: ${lastEvent.log}`);
    }

    if (RUNNING_STATUSES.has(status)) {
      printRunningSummary(modelId, model);
      return model;
    }

    if (FAILED_STATUSES.has(status)) {
      console.error(`[FAILED] Deployment failed. Status: ${status}`);
      if (events.length > 0) {
        console.error("Events:");
        printEvents(model);
      }
      throw new Error(`Deployment failed with status ${status}`);
    }
  }

  throw new Error(`Polling timed out after ${Math.floor((MAX_POLLS * POLL_INTERVAL_MS) / 1000)}s for model ${modelId}`);
}

async function deploy() {
  const token = getToken();
  if (!token) {
    throw new Error("No Control Plane token found");
  }

  const body = buildDeployBody();
  console.log(`[INFO] Deploying ${HF_MODEL_ID} to Tensormesh...`);

  const response = await requestJson(`${CONTROL_PLANE_BASE}/v1/models`, {
    method: "POST",
    token,
    body,
  });

  if (!response.ok) {
    throw new Error(`Deploy failed - HTTP ${response.status}\n${formatPayload(response.data)}`);
  }

  const model = normalizeModel(response.data);
  const modelId = model.modelId || model.id || response.data?.modelId || response.data?.id;
  if (!modelId) {
    throw new Error(`Deployment succeeded but no modelId was returned\n${formatPayload(response.data)}`);
  }

  console.log(`[SUCCESS] Deployment created - modelId: ${modelId}`);
  console.log("[INFO] Polling status...");
  await pollStatus(modelId, token);
}

async function checkActive(modelIdArg) {
  const token = getToken();
  if (!token) {
    throw new Error("No Control Plane token found");
  }

  const modelId = safeTrim(modelIdArg) || ACTIVE_MODEL_ID;
  if (!modelId) {
    throw new Error("No active model ID provided");
  }

  console.log(`[INFO] Checking deployment: ${modelId}`);
  await pollStatus(modelId, token);
}

async function printBody() {
  const body = buildDeployBody();
  process.stdout.write(`${JSON.stringify(body, null, 2)}\n`);
}

async function main() {
  if (typeof fetch !== "function") {
    throw new Error("Global fetch is not available. Use Node.js 18+.");
  }

  const mode = safeTrim(process.argv[2] || "deploy").toLowerCase();
  const arg = process.argv[3];

  if (mode === "deploy") {
    await deploy();
    return;
  }

  if (mode === "status") {
    await checkActive(arg);
    return;
  }

  if (mode === "body") {
    await printBody();
    return;
  }

  throw new Error(`Unknown mode: ${mode}. Use "deploy", "status", or "body".`);
}

main().catch((err) => {
  console.error("[FATAL]", err?.message || String(err));
  process.exit(1);
});
```
